// Fetch slot summaries in bulk (include booking_id for revenue computation)
const eventIds = data.map((e) => e.id)
const { data: slots } = await supabase
  .from('flash_event_slots')
  .select('flash_event_id, status, booking_id')
  .in('flash_event_id', eventIds)

const summaryMap = new Map<
  string,
  { total: number; booked: number; available: number; bookedBookingIds: string[] }
>()
for (const slot of slots ?? []) {
  const existing = summaryMap.get(slot.flash_event_id) ?? {
    total: 0,
    booked: 0,
    available: 0,
    bookedBookingIds: [],
  }
  existing.total += 1
  if (slot.status === 'booked') {
    existing.booked += 1
    if (slot.booking_id) existing.bookedBookingIds.push(slot.booking_id)
  }
  if (slot.status === 'open') existing.available += 1
  summaryMap.set(slot.flash_event_id, existing)
}

// Collect all booking IDs across all events for a single query
const allBookingIds: string[] = []
for (const summary of summaryMap.values()) {
  allBookingIds.push(...summary.bookedBookingIds)
}

// Fetch deposit info for booked slots' bookings
const depositMap = new Map<string, { deposit_cents: number; deposit_paid: boolean }>()
if (allBookingIds.length > 0) {
  const { data: bookings } = await supabase
    .from('bookings')
    .select('id, deposit_cents, deposit_paid')
    .in('id', allBookingIds)

  for (const b of bookings ?? []) {
    depositMap.set(b.id, { deposit_cents: b.deposit_cents, deposit_paid: b.deposit_paid })
  }
}

// Build per-event booking_id → flash_event_id lookup
const bookingToEvent = new Map<string, string>()
for (const slot of slots ?? []) {
  if (slot.booking_id && slot.status === 'booked') {
    bookingToEvent.set(slot.booking_id, slot.flash_event_id)
  }
}

// Compute revenue aggregates per event
const revenueLockedMap = new Map<string, number>()
const revenueCollectedMap = new Map<string, number>()

for (const [eventId, summary] of summaryMap.entries()) {
  const event = data.find((e) => e.id === eventId)
  const pricePerSlot = event?.slot_price_cents ?? 0
  revenueLockedMap.set(eventId, summary.booked * pricePerSlot)
}

for (const [bookingId, booking] of depositMap.entries()) {
  const eventId = bookingToEvent.get(bookingId)
  if (!eventId) continue
  if (booking.deposit_paid) {
    const prev = revenueCollectedMap.get(eventId) ?? 0
    revenueCollectedMap.set(eventId, prev + booking.deposit_cents)
  }
}

return data.map((event) => ({
  ...event,
  artist: (event.artist as FlashEventListItem['artist']) ?? null,
  location: (event.location as FlashEventListItem['location']) ?? null,
  slot_summary: summaryMap.get(event.id) ?? { total: 0, booked: 0, available: 0 },
  revenue_locked_cents: revenueLockedMap.get(event.id) ?? 0,
  revenue_collected_cents: revenueCollectedMap.get(event.id) ?? 0,
}))

// ── Flash events KPI strip query ─────────────────────────────────────────────

export async function getFlashEventsKPIs(studioId: string): Promise<FlashEventsKPIs> {
  const supabase = await createClient()
  const today = new Date().toISOString().split('T')[0]
  const in30Days = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]

  // Count upcoming events (draft or published, event_date >= today)
  const { count: upcomingCount } = await supabase
    .from('flash_events')
    .select('id', { count: 'exact', head: true })
    .eq('studio_id', studioId)
    .gte('event_date', today)
    .in('status', ['draft', 'published'])

  // Get events in next 30 days to compute slots filled + revenue
  const { data: upcomingEvents } = await supabase
    .from('flash_events')
    .select('id, slot_price_cents')
    .eq('studio_id', studioId)
    .gte('event_date', today)
    .lte('event_date', in30Days)

  const upcomingEventIds = (upcomingEvents ?? []).map((e) => e.id)

  // Default KPIs if no upcoming events
  if (upcomingEventIds.length === 0) {
    return {
      upcoming: upcomingCount ?? 0,
      slotsFilled: { booked: 0, total: 0 },
      revenueLockedCents: 0,
      depositsHeldCents: 0,
    }
  }

  // Slot counts and booking IDs for next-30d events
  const { data: slots30d } = await supabase
    .from('flash_event_slots')
    .select('flash_event_id, status, booking_id')
    .in('flash_event_id', upcomingEventIds)

  const priceMap = new Map<string, number>(
    (upcomingEvents ?? []).map((e) => [e.id, e.slot_price_cents])
  )

  let totalSlots = 0
  let bookedSlots = 0
  let revenueLockedCents = 0
  const bookedBookingIds: string[] = []

  for (const slot of slots30d ?? []) {
    totalSlots += 1
    if (slot.status === 'booked') {
      bookedSlots += 1
      const price = priceMap.get(slot.flash_event_id) ?? 0
      revenueLockedCents += price
      if (slot.booking_id) bookedBookingIds.push(slot.booking_id)
    }
  }

  // Deposits held: sum deposit_cents where deposit_paid = true for upcoming events
  let depositsHeldCents = 0
  if (bookedBookingIds.length > 0) {
    const { data: depositBookings } = await supabase
      .from('bookings')
      .select('deposit_cents, deposit_paid')
      .in('id', bookedBookingIds)
      .eq('deposit_paid', true)

    for (const b of depositBookings ?? []) {
      depositsHeldCents += b.deposit_cents
    }
  }

  return {
    upcoming: upcomingCount ?? 0,
    slotsFilled: { booked: bookedSlots, total: totalSlots },
    revenueLockedCents,
    depositsHeldCents,
  }
}

