import { getFlashEventsKPIs } from '@/lib/flash-events/queries'
import { formatCurrency } from '@/lib/utils'
import { Skeleton } from '@/components/ui/skeleton'

interface Props {
  studioId: string
}

// Server Component — no 'use client'
export async function FlashEventsStatStrip({ studioId }: Props) {
  const kpis = await getFlashEventsKPIs(studioId)

  const cards: {
    label: string
    value: string
    hero?: boolean
  }[] = [
    {
      label: 'Upcoming',
      value: String(kpis.upcoming),
    },
    {
      label: 'Slots filled · 30D',
      value: `${kpis.slotsFilled.booked} / ${kpis.slotsFilled.total}`,
    },
    {
      label: 'Revenue locked',
      value: formatCurrency(kpis.revenueLockedCents),
      hero: true,
    },
    {
      label: 'Deposits held',
      value: formatCurrency(kpis.depositsHeldCents),
    },
  ]

  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      {cards.map((card) => (
        <div
          key={card.label}
          className={[
            'rounded-lg border border-border/60 bg-background p-4 shadow-soft',
            card.hero ? 'border-l-2 border-l-destructive' : '',
          ]
            .filter(Boolean)
            .join(' ')}
        >
          <p className="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
            {card.label}
          </p>
          <p className="mt-1.5 font-bold text-2xl tabular-nums text-foreground">{card.value}</p>
        </div>
      ))}
    </div>
  )
}

export function FlashEventsStatStripSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      {[0, 1, 2, 3].map((i) => (
        <Skeleton key={i} className="h-20 rounded-lg" />
      ))}
    </div>
  )
}

